import{_ as s,c as t,o as r,j as e,a as n}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"卦材第三","description":"杭氏易学 - 卦材第三","frontmatter":{"title":"卦材第三","description":"杭氏易学 - 卦材第三"},"headers":[],"relativePath":"zh/classics/hangshi/004.md","filePath":"zh/classics/hangshi/004.md"}'),i={name:"zh/classics/hangshi/004.md"};function c(o,a,l,d,h,p){return r(),t("div",null,[...a[0]||(a[0]=[e("h1",{id:"卦材第三",tabindex:"-1"},[n("卦材第三 "),e("a",{class:"header-anchor",href:"#卦材第三","aria-label":"Permalink to “卦材第三”"},"​")],-1),e("p",null,"程朱《传》、《义》，宗王《注》，其释《彖》、《象》，均以卦德卦义卦名为言。来知德氏《集注》言性情，以内卦为性，外卦为情，意非不当，要皆强为之名。实则孔子《系传》、《说卦》，当名辨物，已有定称。《传》曰：“彖者，才也。才也者，材也。”言材则体用皆赅，德性兼备无余蕴矣。《说卦》“雷动风散”，“乾健坤顺”两章，皆言八卦之材。知八卦象之材，而后知六十四卦因重交互，无不各因其材。而辨其情伪吉凶，铢两悉称，名实相副。《彖》、《象》传赞，亦无不各因其材以为之辞，无一字之虚设焉。学者宜详玩经文，而合之于象，准之于数，融会贯通，由一卦以推各卦，而观一卦，更必遍取各卦，参互比例，而后能得其真确之意义。不可因字义注释之已明，而不复研求深意之所在焉。",-1),e("p",null,"健顺动入陷丽止说，各一字概一卦之德性功用。而父母男女，亦各因其名，以定一卦之分际。今皆谓之材者，以六十四卦之《彖》、《象》，无不合内外两卦之材以命辞。而一卦六爻，及内外中爻，亦无不取材于是。《传》曰：“君子观其彖辞，则思过半矣。”彖辞因材而施之辞也，且不特内外卦为然。即卦中之一爻，为何卦之爻，即具何卦之材。如为坎爻必有陷义，或险义。为离爻者，必具明义，或丽义。惟乾坤两卦，不以爻言。而《杂卦》之“震起兑见巽伏艮止”，此“起止见伏”四字，尤为八卦变化之门。观象玩辞，均不可不于此郑重注意也。",-1)])])}const f=s(i,[["render",c]]);export{_ as __pageData,f as default};
